const job = await tools.job_output({ job_id: "pwsh-196", wait: true, timeout_ms: 350000 });
console.log("status:", job.job.status);
console.log("output:", (job.text ?? "").slice(-1000));
const fs = await import("node:fs");
try {
  const t = fs.readFileSync("C:/Users/jjq21/AppData/Local/Temp/ofm-subs-out.txt", "utf8");
  console.log("\nFILE LEN:", t.length);
  const lines = t.split("\n");
  for (const l of lines) {
    if (l.startsWith("##########")) console.log("\n" + l);
    else if (l.startsWith("ENTRIES")) console.log(l);
    else if (l.startsWith("--- ")) console.log("  " + l.slice(4, 120));
    else if (l.includes("DONE")) console.log(l);
  }
} catch (e) { console.log("file err", (e as Error).message); }
